<script setup lang="ts">
import {shallowRef} from 'vue'
import {Table,Popconfirm,message} from 'ant-design-vue'
import StatePanel from '@starbeacon/shared/components/StatePanel.vue'
import {formatTime} from '@starbeacon/shared/types.ts'
import {useModels} from '../models/useModels'
import {kindNames} from './analysis'
import {useAnalysis} from './useAnalysis'
import {useReportPlans} from './useReportPlans'
import {planCodes,planRunState,type ReportPlan,type ReportPlanChange,type ReportPlanRun} from './plans'
import ReportPlanForm from './ReportPlanForm.vue'
import AnalysisDetail from './AnalysisDetail.vue'
const state=useReportPlans(),models=useModels(),analysis=useAnalysis('reports')
const {items,available,modelsAvailable,pending,error,busy,actionError,unconfirmed,runs,next,runsPending,runsError}=state
const editing=shallowRef<ReportPlan|null>(null),editorOpen=shallowRef(false),selected=shallowRef<ReportPlan|null>(null),detailOpen=shallowRef(false),viewing=shallowRef('')
const columns=[{title:'计划名称',key:'name',width:200},{title:'报告周期',key:'kind',width:120},{title:'时区 / 执行时间',key:'clock',width:220},{title:'智能总结',key:'provider',width:160},{title:'状态',key:'state',width:100},{title:'下次计划时间',key:'next',width:190},{title:'操作',key:'actions',width:190,fixed:'right' as const}]
const runColumns=[{title:'报告周期',key:'period',width:170},{title:'状态',key:'state',width:160},{title:'计划 / 实际槽位',key:'due',width:230},{title:'处理说明',key:'reason',width:280},{title:'操作',key:'action',width:110,fixed:'right' as const}]
function edit(record:ReportPlan|null){if(busy.value||unconfirmed.value)return;state.clearAction();editing.value=record;editorOpen.value=true}
async function save(change:ReportPlanChange){if(await state.save(change)){editorOpen.value=false;message.success('报告计划已保存')}}
async function confirm(){if(await state.confirm()){editorOpen.value=false;message.success('报告计划保存结果已确认')}}
async function disable(record:ReportPlan){if(await state.save({id:record.id,expected_revision:record.revision,spec:{...record.spec,enabled:false}}))message.success('报告计划已停用')}
async function showRuns(record:ReportPlan){selected.value=record;await state.loadRuns(record.id)}
function closeRuns(){selected.value=null;state.closeRuns();detailOpen.value=false;analysis.clear();void state.refresh()}
async function showReport(id:string){analysis.clear();viewing.value=id;detailOpen.value=true;await analysis.loadJob(id)}
</script>
<template>
 <header class="page-header"><div><h1>报告中心</h1><p class="page-description">{{selected?selected.spec.name+'的计划运行记录，可核对周期、错过范围与报告处理结果。':'按时区定时生成安全日报、周报与月报，管理持续模型授权和运行记录。'}}</p></div><div class="filter-actions"><template v-if="selected"><a-button @click="closeRuns">返回计划</a-button><a-button :loading="runsPending" @click="state.loadRuns(selected.id)">刷新记录</a-button></template><template v-else><a-button :loading="pending" @click="state.refresh">刷新</a-button><a-button type="primary" :disabled="pending||busy||unconfirmed||!!error||items.length>=32" @click="edit(null)">创建计划</a-button></template></div></header>
 <a-alert v-if="actionError&&!editorOpen" type="error" :message="actionError" show-icon class="section-gap"/>
 <a-alert v-if="unconfirmed&&!editorOpen" type="warning" message="计划操作结果尚未确认，请确认原请求后继续。" show-icon class="section-gap"><template #action><a-button :loading="busy" @click="confirm">确认保存结果</a-button></template></a-alert>
 <a-alert v-if="!selected&&!pending&&!available&&!error" type="info" message="报告计划执行服务暂不可用，可核对已有计划或保存停用配置。" show-icon class="section-gap"/>
 <a-alert v-if="!selected&&models.error.value" type="warning" :message="models.error.value+'。可使用统计报告计划。'" show-icon class="section-gap"/>
 <section v-if="!selected" class="panel"><div class="panel-header"><h2>报告计划</h2><span>当前账号 {{items.length}} 个 · 每租户最多 32 个</span></div><a-alert v-if="error&&items.length" type="error" :message="error+'。当前显示上次成功读取的计划。'" show-icon class="section-gap"><template #action><a-button @click="state.refresh">重试</a-button></template></a-alert><StatePanel :loading="pending&&!items.length" :error="items.length?'':error" :empty="!items.length" description="暂无报告计划，可配置周期、时区与执行时间生成统计报告。" @retry="state.refresh"><div class="table-wrap"><Table :columns="columns" :data-source="[...items]" row-key="id" :pagination="false" :scroll="{x:1180}"><template #bodyCell="{column,record}">
  <template v-if="column.key==='name'">{{record.spec.name}}<small class="record-id">修订 {{record.revision}}</small></template><template v-else-if="column.key==='kind'">{{kindNames[record.spec.kind as 'daily'|'weekly'|'monthly']}}</template><template v-else-if="column.key==='clock'"><span class="plan-value">{{record.spec.timezone}}</span><small class="record-id">{{record.spec.at}}</small></template><template v-else-if="column.key==='provider'"><template v-if="record.spec.provider_id"><span class="plan-value">{{models.items.value.find(p=>p.id===record.spec.provider_id)?.name??'固定模型修订'}}</span><small class="record-id">模型修订 {{record.spec.provider_revision}}</small></template><template v-else>统计报告</template></template><template v-else-if="column.key==='state'"><span :class="['status',record.spec.enabled?'status-online':'status-disabled']">{{record.spec.enabled?'启用':'停用'}}</span></template><template v-else-if="column.key==='next'">{{record.next_at?formatTime(record.next_at):'未安排执行'}}</template><template v-else-if="column.key==='actions'"><div class="filter-actions"><a-button type="link" size="small" :disabled="busy||unconfirmed||pending" @click="edit(record as ReportPlan)">配置</a-button><a-button type="link" size="small" :disabled="busy||unconfirmed" @click="showRuns(record as ReportPlan)">运行记录</a-button><Popconfirm v-if="record.spec.enabled" title="停用报告计划？" description="后续周期不再生成，已提交的报告继续处理。" ok-text="停用计划" cancel-text="取消" :disabled="busy||unconfirmed" @confirm="disable(record as ReportPlan)"><a-button type="link" size="small" :disabled="busy||unconfirmed">停用</a-button></Popconfirm></div></template>
 </template></Table></div></StatePanel></section>
 <section v-else class="panel"><div class="panel-header"><h2>计划运行记录</h2><span>计划修订 {{selected.revision}}</span></div><a-alert v-if="runsError&&runs.length" type="error" :message="runsError+'。当前显示上次成功读取的运行记录。'" show-icon class="section-gap"><template #action><a-button @click="state.loadRuns(selected.id)">重试</a-button></template></a-alert><StatePanel :loading="runsPending&&!runs.length" :error="runs.length?'':runsError" :empty="!runs.length" description="暂无运行记录，计划到期后可核对生成结果。" @retry="state.loadRuns(selected.id)"><div class="table-wrap"><Table :columns="runColumns" :data-source="[...runs]" row-key="id" :pagination="false" :scroll="{x:950}"><template #bodyCell="{column,record}"><template v-if="column.key==='period'">{{kindNames[record.request.kind as 'daily'|'weekly'|'monthly']}} · {{record.request.period}}<small class="record-id">计划修订 {{record.plan_revision}}</small></template><template v-else-if="column.key==='state'"><span :class="['status',record.analysis_state==='succeeded'?'status-online':record.state==='failed'||record.analysis_state==='failed'?'status-offline':'status-pending']">{{planRunState(record as ReportPlanRun)}}</span></template><template v-else-if="column.key==='due'">{{formatTime(record.due_at)}}<small class="record-id">实际槽位 {{formatTime(record.effective_at)}}</small></template><template v-else-if="column.key==='reason'"><span>{{Object.hasOwn(planCodes,record.code)?planCodes[record.code]:record.state==='preparing'?'统计正在准备':'请核对运行状态'}}</span><small v-if="record.skipped_from" class="record-id">错过槽位范围：{{formatTime(record.skipped_from)}} 至 {{formatTime(record.skipped_until)}}（不含结束时刻）；仅生成最近完整周期。</small></template><a-button v-else-if="column.key==='action'" type="link" size="small" :disabled="!record.analysis_id||!record.analysis_state" @click="showReport(record.analysis_id)">查看报告</a-button></template></Table></div><a-button v-if="next" class="section-gap" :loading="runsPending" @click="state.loadRuns(selected.id,next)">查看更多记录</a-button></StatePanel></section>
 <ReportPlanForm v-if="editorOpen" :record="editing" :providers="models.items.value" :available="available" :models-available="modelsAvailable" :busy="busy" :error="actionError" :unconfirmed="unconfirmed" @save="save" @confirm="confirm" @close="editorOpen=false"/>
 <AnalysisDetail :open="detailOpen" :job="analysis.selected.value" :loading="analysis.loading.value" :error="analysis.detailError.value" :busy="analysis.busy.value" @close="detailOpen=false;analysis.clear()" @retry="analysis.loadJob(viewing)" @cancel="analysis.cancel"/>
</template>
<style scoped>.plan-value{overflow-wrap:anywhere;word-break:break-word}</style>
